/**
 * GENERATED FILE PRODUCER — writes lib/geometry/__fixtures__/phase16-litres-pin.json: the litres of
 * the forty Phase 16 test boards (`phase16Boards`, lib/geometry/__fixtures__/phase16-boards.ts) as the
 * app worked them out BEFORE the litres and the 3D board shared one section function (research
 * Pattern 1, D-05). The output is generated and must never be hand-edited.
 *
 *   npx --no-install tsx --tsconfig ./tsconfig.json scripts/extract-phase16-litres-pin.ts
 *
 * run from the repository root. Like the pin of Phase 14's numbers, it is a record of the code as it
 * stood, so it REFUSES to run once `lib/geometry/volume.ts` exports `boardSections`: from then on the
 * figures it would write are the refactor's own, and the pin would prove nothing. It ran exactly once.
 * (Nothing in package.json — `--no-install` means npx can only run the tsx already in node_modules.
 * No database is involved.)
 *
 * Each figure is `summarizeDesign(fields).volumeLitres.toPrecision(17)`, a string, so the test
 * compares every digit a double holds.
 */
import { existsSync, writeFileSync } from "node:fs";
import path from "node:path";
import { phase16Boards } from "@/lib/geometry/__fixtures__/phase16-boards";
import { summarizeDesign } from "@/lib/geometry/design";
import * as volume from "@/lib/geometry/volume";

const OUTPUT = path.resolve(process.cwd(), "lib/geometry/__fixtures__/phase16-litres-pin.json");

function main() {
  if (!existsSync(path.resolve(process.cwd(), "lib/geometry/volume.ts"))) {
    throw new Error("Run this from the repository root (lib/geometry/volume.ts not found here).");
  }
  if ("boardSections" in volume) {
    throw new Error("the pin records the litres from before boardSections existed — it is never re-run");
  }
  const litres: Record<string, string> = {};
  for (const board of phase16Boards()) {
    litres[board.label] = summarizeDesign(board.fields).volumeLitres.toPrecision(17);
  }
  const provenance =
    "GENERATED by scripts/extract-phase16-litres-pin.ts from the app as it stood before boardSections " +
    "(phase16Boards, summarizeDesign, toPrecision(17)) — never hand-edit, never re-run";
  writeFileSync(OUTPUT, `${JSON.stringify({ provenance, litres }, null, 2)}\n`);
  for (const [label, value] of Object.entries(litres)) console.log(`${label}: ${Number(value).toFixed(4)} L`);
  console.log(`wrote ${path.relative(process.cwd(), OUTPUT)} (${Object.keys(litres).length} boards)`);
}

try {
  main();
} catch (error: unknown) {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
}
